  test("bhv authoauthtwotokenmgr 027 coalesces concurrent refresh calls into single token request", async () => {
    let pendingResolve: ((value: ApiHttpResponse) => void) | null = null;
    let networkCalls = 0;

    class SlowMockApiClient implements ApiClient {
      async sendRequest(): Promise<ApiHttpResponse> {
        networkCalls++;
        return new Promise<ApiHttpResponse>((resolve) => {
          pendingResolve = resolve;
        });
      }
    }

    const manager = new OAuth2TokenManager();
    manager.setApiClient(new SlowMockApiClient());

    const requests = Array.from({ length: 10 }, () =>
      manager.getAccessToken("https://auth.example.com/token", {
        grant_type: "client_credentials",
      }),
    );

    // Allow the queued microtasks to schedule.
    await new Promise((resolve) => setImmediate(resolve));

    expect(networkCalls).toBe(1);
    expect(pendingResolve).not.toBeNull();
    pendingResolve!({
      statusCode: 200,
      body: JSON.stringify({
        access_token: "concurrent-token",
        expires_in: 3600,
      }),
      headers: { "content-type": "application/json" },
    });

    const tokens = await Promise.all(requests);
    expect(tokens.every((t) => t === "concurrent-token")).toBe(true);
    expect(networkCalls).toBe(1);
  });

