  /*
   * Gap 3.2: the token POST must opt out of redirect following at the
   * transport layer (noRedirect: true) AND additionally refuse any 3xx
   * status it does see, so callers get a loud error instead of the
   * silent "missing access_token" fall-through.
   */
  describe("redirect refusal on token endpoint", () => {
    test("bhv authoauthtwotokenmgr 034 passes noRedirect=true to the transport on every token POST", async () => {
      mockClient.responseBody = JSON.stringify({
        access_token: "tok",
        expires_in: 3600,
      });
      await tokenManager.getAccessToken("https://auth.example.com/token", {
        grant_type: "client_credentials",
      });
      expect(mockClient.lastOptions).toBeDefined();
      expect(mockClient.lastOptions?.noRedirect).toBe(true);
      expect(mockClient.lastOptions?.noDefaultHeaders).toBe(true);
    });

    /* A 3xx is a non-2xx answer, so the refusal is an OAuth2ServerError
     * carrying the status. */
    test("bhv authoauthtwotokenmgr 033 token endpoint redirect is rejected", async () => {
      for (const status of [301, 302, 303, 307, 308]) {
        mockClient.responseStatus = status;
        mockClient.responseBody = "";
        mockClient.responseHeaders = {
          "content-type": "text/plain",
          location: "https://attacker.example/steal",
        };

        await expect(
          tokenManager.getAccessToken("https://auth.example.com/token", {
            grant_type: "client_credentials",
            client_secret: "topsecret",
          }),
        ).rejects.toBeInstanceOf(OAuth2ServerError);
        // INVARIANT: every SDK-thrown error reaches the branded OpenAPIError root.
        await expect(
          tokenManager.getAccessToken("https://auth.example.com/token", {
            grant_type: "client_credentials",
            client_secret: "topsecret",
          }),
        ).rejects.toBeInstanceOf(OpenAPIError);
        await expect(
          tokenManager.getAccessToken("https://auth.example.com/token", {
            grant_type: "client_credentials",
            client_secret: "topsecret",
          }),
        ).rejects.toMatchObject({ statusCode: status });
      }
    });
  });
